//! Build one relocatable, privately named SQLite runtime for all engine images.

use std::collections::BTreeSet;
use std::env;
use std::fmt::Write as _;
use std::fs;
use std::path::Path;

const LIBRARY: &str = "mikrio_sqlite3";
const PREFIX: &str = "mikrio_sqlite3_v1_";
const SOURCE: &str = "0c657666d819f261cc4007526ad57e1669de9949df7a8ea847aa284a2bf0ee52";

pub fn compile(build: &mut cc::Build, output: &Path, bindings: &Path) {
    println!("cargo:rerun-if-changed=mikrio_shared.rs");
    println!("cargo:rerun-if-changed=sqlite3/bindgen_bundled_version.rs");
    println!("cargo:rerun-if-changed=sqlite3/sqlite3.h");

    let target = env::var("CARGO_CFG_TARGET_OS").unwrap();
    let filename = match target.as_str() {
        "macos" => format!("lib{LIBRARY}.dylib"),
        "linux" => format!("lib{LIBRARY}.so"),
        "windows" => format!("{LIBRARY}.dll"),
        _ => panic!("Unsupported Mikrio SQLite target: {target}"),
    };
    let compiler = build.get_compiler();
    let msvc = compiler.is_like_msvc();
    let mut identity = format!("{PREFIX}\n{SOURCE}\n");

    // Include ABI/behavior-changing definitions and instrumentation, but not
    // optimization, debug paths or an executor's absolute SDK location.
    let mut arguments = compiler.args().iter();
    while let Some(argument) = arguments.next() {
        let mut argument = argument
            .to_str()
            .expect("non-UTF-8 SQLite compiler option")
            .to_owned();
        if argument == "-D" || argument == "-U" || (msvc && (argument == "/D" || argument == "/U"))
        {
            let value = arguments
                .next()
                .expect("missing SQLite compiler definition")
                .to_str()
                .expect("non-UTF-8 SQLite compiler definition");
            argument.push_str(value);
        }

        if argument.starts_with("-D")
            || argument.starts_with("-U")
            || argument.starts_with("-fsanitize=")
            || argument.starts_with("-fno-sanitize=")
            || (msvc && (argument.starts_with("/D") || argument.starts_with("/U")))
        {
            writeln!(identity, "{argument}").unwrap();
        }
    }

    let header = output.join("mikrio_namespace.h");
    namespace(bindings, &header);
    let visibility = if target == "windows" {
        "__declspec(dllexport)"
    } else {
        "__attribute__((visibility(\"default\")))"
    };
    let runtime = output.join("mikrio_runtime.c");
    let literal: String = identity
        .bytes()
        .map(|byte| format!("\\x{byte:02x}"))
        .collect();
    fs::write(
        &runtime,
        format!("{visibility} const char *{PREFIX}identity(void) {{ return \"{literal}\"; }}\n"),
    )
    .unwrap();
    fs::write(
        output.join("mikrio_runtime.rs"),
        format!(
            r#"// Generated by mikrio_shared.rs from the reviewed source and compiler options.
unsafe extern "C" {{
    fn {PREFIX}identity() -> *const core::ffi::c_char;
}}

/// Whether this engine and the process's shared SQLite runtime have the same build policy.
/// This check performs no SQLite initialization or filesystem access.
pub fn mikrio_runtime_matches() -> bool {{
    // SAFETY: the private runtime ABI returns a process-lifetime NUL-terminated
    // string. No SQLite connection or host-owned allocation crosses this call.
    let actual = unsafe {{ core::ffi::CStr::from_ptr({PREFIX}identity()) }};
    actual.to_bytes() == {identity:?}.as_bytes()
}}
"#
        ),
    )
    .unwrap();

    build.cargo_metadata(false).pic(true).file(runtime);
    build.define("SQLITE_API", Some(visibility));
    if msvc {
        build.flag(format!("/FI{}", header.display()));
    } else {
        build
            .flag("-fvisibility=hidden")
            .flag("-include")
            .flag(header.to_str().unwrap());
    }

    let objects = build.compile_intermediates();
    let mut linker = compiler.to_command();
    linker.args(objects);

    match target.as_str() {
        "macos" => {
            linker.args([
                "-dynamiclib",
                "-Wl,-install_name,@rpath/libmikrio_sqlite3.dylib",
            ]);
            linker.arg("-o").arg(output.join(&filename));
        }
        "linux" => {
            linker.args([
                "-shared",
                "-Wl,-soname,libmikrio_sqlite3.so",
                "-Wl,-z,relro,-z,now",
            ]);
            linker.arg("-o").arg(output.join(&filename));
            linker.args(["-lpthread", "-ldl", "-lm"]);
        }
        "windows" if msvc => {
            linker
                .arg("/LD")
                .arg(format!("/Fe:{}", output.join(&filename).display()));
            linker.arg("/link").arg(format!(
                "/IMPLIB:{}",
                output.join("mikrio_sqlite3.lib").display()
            ));
        }
        "windows" => {
            linker.arg("-shared").arg("-o").arg(output.join(&filename));
            linker.arg(format!(
                "-Wl,--out-implib,{}",
                output.join("libmikrio_sqlite3.dll.a").display()
            ));
        }
        _ => unreachable!(),
    }

    let result = linker
        .status()
        .expect("cannot execute shared SQLite linker");
    assert!(result.success(), "shared SQLite link failed: {result}");
    println!("cargo:rustc-link-search=native={}", output.display());
    println!("cargo:rustc-link-lib=dylib={LIBRARY}");
    println!("cargo:runtime={}", output.join(filename).display());
}

fn namespace(bindings: &Path, header: &Path) {
    // Rename only public declarations, including APIs absent from the Rust
    // bindings. Defining internal configuration macros would change SQLite's
    // conditional compilation rather than merely isolate its symbols.
    let source = fs::read_to_string("sqlite3/sqlite3.h").unwrap();
    let symbols: BTreeSet<_> = source
        .lines()
        .filter(|line| line.starts_with("SQLITE_API "))
        .map(|line| {
            line.split('(')
                .next()
                .unwrap()
                .split(|character: char| !character.is_ascii_alphanumeric() && character != '_')
                .filter(|word| word.starts_with("sqlite3"))
                .next_back()
                .expect("unrecognized SQLite public declaration")
        })
        .collect();
    assert_eq!(
        symbols.len(),
        370,
        "review the changed SQLite public header"
    );
    let mut definitions = String::from("/* Generated by mikrio_shared.rs. */\n");
    for symbol in &symbols {
        writeln!(definitions, "#define {symbol} {PREFIX}{symbol}").unwrap();
    }
    fs::write(header, definitions).unwrap();

    let original = fs::read_to_string(bindings).unwrap();
    let mut rewritten = String::new();
    for line in original.lines() {
        let declaration = line.trim_start();
        let name = declaration
            .strip_prefix("pub fn ")
            .or_else(|| declaration.strip_prefix("pub static mut "))
            .or_else(|| declaration.strip_prefix("pub static "));
        if let Some(name) = name {
            let name = name.split(['(', ':']).next().unwrap().trim();
            assert!(symbols.contains(name), "unknown SQLite binding: {name}");
            writeln!(rewritten, "    #[link_name = \"{PREFIX}{name}\"]").unwrap();
        }
        writeln!(rewritten, "{line}").unwrap();
    }
    fs::write(bindings, rewritten).unwrap();
}
